#!/usr/bin/env -S uv run --script
# Synced from bootstrap: macos/tools/claude-cli/tasks/func-claude.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Start Claude Code (Remote Control), session named after the current folder"
# MISE hide=true
# MISE dir="{{cwd}}"
# MISE tools={uv="latest", python="3.14"}

# USAGE arg "<name>" default="" help="Optional name to append to the session"
# USAGE flag "-n --new" help="Start a new session instead of resuming"
# USAGE flag "-m --model <model>" help="Specify the model to use for the Claude session" {
# USAGE   choices "fable[1m]" "haiku[1m]" "opus[1m]" "sonnet[1m]"
# USAGE }

#
# Usage: mise run func:claude [--model <model>] [name] [claude args...]

import os
import shutil
import sys


def user_env():
  """The environment of the user for the tool: without VIRTUAL_ENV and
  without the bin folder of the script environment on PATH, which uv run
  adds."""
  env = dict(os.environ)
  env.pop("VIRTUAL_ENV", None)
  script_bin = os.path.normpath(os.path.join(sys.prefix, "bin"))
  path = env.get("PATH", "").split(os.pathsep)
  env["PATH"] = os.pathsep.join(p for p in path if os.path.normpath(p) != script_bin)
  return env


def current_folder():
  """The current folder as $PWD of the shell gives it: PWD when it is the
  current folder, else the physical path."""
  pwd = os.environ.get("PWD", "")
  try:
    if os.path.isabs(pwd) and os.path.samefile(pwd, "."):
      return pwd
  except OSError:
    pass
  return os.getcwd()


def main():
  # Claude Code is the claude tool's, which is opt-in
  if not shutil.which("claude"):
    print("Claude Code is not installed or not in PATH.", flush=True)
    sys.exit(1)

  # Determine if a new session should be started based on the usage flag
  new_session = os.environ.get("usage_new", "false") == "true"

  # Initialize the session name based on the current folder and optional name suffix
  session = os.path.basename(current_folder())
  name = os.environ.get("usage_name", "")
  if name:
    session += f"-{name}"

  # Initialize the arguments list with the session name
  args = ["--name", session]

  # Add the resume flag if not starting a new session
  if not new_session:
    args += ["--resume", session]

  # Add the model flag if specified
  model = os.environ.get("usage_model", "")
  if model:
    args += ["--model", model]

  # Add the dangerously skip permissions flag to the arguments list
  args += ["--remote-control"]
  args += ["--dangerously-skip-permissions"]
  args += ["--allow-dangerously-skip-permissions"]

  # The process of claude replaces this process.
  sys.stdout.flush()
  os.execvpe("claude", ["claude", *args], user_env())


if __name__ == "__main__":
  main()
